-- OMP Security Academy schema + seed
create table if not exists public.learning_categories (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, description text, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.learning_topics (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.learning_categories(id) on delete cascade, slug text not null, name text not null, description text, difficulty text not null default 'Beginner', estimated_minutes integer not null default 15, sort_order integer not null default 0, status text not null default 'published', content jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(category_id,slug));
create table if not exists public.learning_labs (id uuid primary key default gen_random_uuid(), topic_id uuid not null references public.learning_topics(id) on delete cascade, title text not null, provider text not null, url text not null, description text, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.learning_quizzes (id uuid primary key default gen_random_uuid(), topic_id uuid not null unique references public.learning_topics(id) on delete cascade, passing_score integer not null default 15, max_score integer not null default 20, questions jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.learning_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, category_id uuid not null references public.learning_categories(id), topic_id uuid not null references public.learning_topics(id) on delete cascade, lesson_started boolean not null default false, lesson_completed boolean not null default false, lab_completed boolean not null default false, quiz_attempts integer not null default 0, highest_score integer not null default 0, passed boolean not null default false, state text not null default 'NOT_STARTED', completed_at timestamptz, next_retry_at timestamptz, last_attempt_at timestamptz, updated_at timestamptz not null default now(), unique(user_id,topic_id));
create table if not exists public.learning_quiz_answers (id uuid primary key default gen_random_uuid(), quiz_id uuid not null references public.learning_quizzes(id) on delete cascade, question_index integer not null, answer_index integer not null, unique(quiz_id,question_index));
create table if not exists public.learning_certificates (id uuid primary key default gen_random_uuid(), certificate_id text not null unique, user_id uuid not null references auth.users(id) on delete cascade, topic_id uuid not null references public.learning_topics(id) on delete cascade, category_id uuid not null references public.learning_categories(id), recipient_name text not null, topic_name text not null, category_name text not null, score integer not null, issued_at timestamptz not null default now(), unique(user_id,topic_id));
insert into public.learning_categories(id,slug,name,description,sort_order,is_active) values ('d93dd172-940d-469c-9e2b-126acfc36bff','web-application-security','Web Application Security','Core web vulnerabilities, secure design concepts, and practical ways to reason about application security.',0,true),('40318254-13cb-4535-84b5-45e78b89f494','api-security','API Security','Security fundamentals for REST, JWT, OAuth, GraphQL, and modern API authorization models.',1,true),('a0812f74-ba5e-489c-b4c6-b2c70fd29558','android-security','Android Security','Foundational Android security concepts for APK review, app components, storage, WebView, and API trust.',2,true),('4cdd5589-329b-4fae-ab52-84250d4cab0e','recon-osint','Recon & OSINT','Asset discovery and public-information analysis with an emphasis on scope, accuracy, and safe research.',3,true),('db46ed02-aa01-4524-bcc8-09c3527173bd','network-security','Network Security','Networking foundations and service-security concepts that support responsible security testing.',4,true),('0f941edb-cb3e-491d-963b-0fba8348313c','cloud-security','Cloud Security','Core cloud-security concepts across identity, storage, and major cloud platforms.',5,true),('306891af-5aba-4a7e-9cea-1c76c8be39ee','client-side-security','Client-Side Security','Browser-side security concepts covering DOM risks, framing, content policy, messaging, and JavaScript isolation.',6,true) on conflict (id) do update set slug=excluded.slug,name=excluded.name,description=excluded.description,sort_order=excluded.sort_order,is_active=excluded.is_active;
