alter table public.learning_categories enable row level security; alter table public.learning_topics enable row level security; alter table public.learning_labs enable row level security; alter table public.learning_quizzes enable row level security; alter table public.learning_progress enable row level security; alter table public.learning_quiz_answers enable row level security; alter table public.learning_certificates enable row level security;
drop policy if exists learning_categories_public_select on public.learning_categories; create policy learning_categories_public_select on public.learning_categories for select to anon,authenticated using (is_active=true);
drop policy if exists learning_topics_public_select on public.learning_topics; create policy learning_topics_public_select on public.learning_topics for select to anon,authenticated using (status='published');
drop policy if exists learning_labs_public_select on public.learning_labs; create policy learning_labs_public_select on public.learning_labs for select to anon,authenticated using (is_active=true);
drop policy if exists learning_quizzes_public_select on public.learning_quizzes; create policy learning_quizzes_public_select on public.learning_quizzes for select to anon,authenticated using (true);
drop policy if exists learning_progress_select_own on public.learning_progress; create policy learning_progress_select_own on public.learning_progress for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists learning_quiz_answers_deny_all on public.learning_quiz_answers; create policy learning_quiz_answers_deny_all on public.learning_quiz_answers for all to anon,authenticated using (false) with check (false);
drop policy if exists learning_certificates_deny_all on public.learning_certificates; create policy learning_certificates_deny_all on public.learning_certificates for all to anon,authenticated using (false) with check (false);
